const GENERATION_SUFFIX = {
  1:{kana:'',latin:''}, 2:{kana:'改',latin:' Refit'}, 3:{kana:'二型',latin:' Type II'}, 4:{kana:'甲',latin:' A'},
  5:{kana:'乙',latin:' B'}, 6:{kana:'丙',latin:' C'}, 7:{kana:'改二',latin:' Refit II'}, 8:{kana:'特',latin:' Special'}, 9:{kana:'極',latin:' Final'},
};

function seriesAdjustments(cfg, slot, generation) {
  const groupAdjustments = {};
  const growthAdjustments = {};
  const weaponAdjustments = {};
  const weaponGrowthAdjustments = {};
  const primary = cfg.focusGroups[slot % cfg.focusGroups.length];
  const secondary = cfg.focusGroups[(slot + 1) % cfg.focusGroups.length];
  const weapon = cfg.focusWeapons[slot % cfg.focusWeapons.length];
  groupAdjustments[primary] = 2 + (slot % 4);
  if (slot % 3 === 0) groupAdjustments[secondary] = 2;
  if (slot % 5 === 4) groupAdjustments[GROUP_KEYS[(slot + generation) % GROUP_KEYS.length]] = -2;
  growthAdjustments[primary] = round3(0.015 + (generation >= 6 ? 0.01 : 0) + (slot % 4) * 0.004);
  weaponAdjustments[weapon] = 3 + (slot % 4);
  weaponGrowthAdjustments[weapon] = round3(0.025 + (slot % 3) * 0.01);
  return {groupAdjustments,growthAdjustments,weaponAdjustments,weaponGrowthAdjustments,preferredWeapons:[weapon]};
}

function buildSeries(makerId, cfg, generation, slot) {
  const number = (generation - 1) * 20 + slot + 1;
  const isG10 = generation === 10;
  const suffix = GENERATION_SUFFIX[generation] ?? {kana:'',latin:''};
  const nameKana = isG10 ? cfg.g10Kana[slot] : `${cfg.rootsKana[slot]}${suffix.kana}`;
  const nameLatin = isG10 ? cfg.g10Latin[slot] : `${cfg.rootsLatin[slot]}${suffix.latin}`;
  const adj = seriesAdjustments(cfg, slot, generation);
  const weaponText = cfg.focusWeapons.map((w)=>({rifle:'ライフル',machineGun:'マシンガン',lance:'ランス',missile:'ミサイル',drone:'ドローン',emp:'EMP',blade:'ブレード'}[w]??w)).join('・');
  const generationText = `第${generation}世代`;
  const series = {
    id:`${makerId}-new-${number}`,
    manufacturerId:makerId,
    seriesNumber:number,
    nameKana,
    nameLatin,
    archetypeId:ARCHETYPES[(slot + (generation-1)*3) % ARCHETYPES.length],
    ...adj,
    reliabilityAdjustment: makerId==='mikage' ? 2 + (slot%3) : makerId==='nomad' ? -3 + (slot%3) : makerId==='tokiwa' ? 3 + (slot%3) : makerId==='heritage' ? 2 + (slot%3) : makerId==='libido' ? (slot%3)-1 : (slot%3)-1,
    resistanceAdjustment: makerId==='meridian' ? -1 : makerId==='heritage' ? 2 + (slot%3) : makerId==='libido' ? -1 + (slot%2) : makerId==='tokiwa' ? 1 + (slot%3===0 ? 1 : 0) : (slot%4===0 ? 1 : 0),
    statVarianceMultiplier: makerId==='nomad' ? 1.12 + (slot%4)*0.04 : makerId==='heritage' ? 0.92 + (slot%3)*0.03 : makerId==='libido' ? 1.12 + (slot%4)*0.04 : makerId==='tokiwa' ? 0.88 + (slot%3)*0.025 : makerId==='mikage' ? 0.9 + (slot%3)*0.03 : 0.98 + (slot%3)*0.03,
    growthVarianceMultiplier: makerId==='nomad' ? 1.15 + (slot%4)*0.05 : makerId==='heritage' ? 0.94 + (slot%3)*0.03 : makerId==='libido' ? 1.16 + (slot%4)*0.045 : makerId==='tokiwa' ? 0.9 + (slot%3)*0.025 : makerId==='mikage' ? 0.92 + (slot%3)*0.03 : 1.0 + (slot%3)*0.03,
    eccentricBonusAdjustment: makerId==='nomad' ? 0.04 + (slot%5)*0.015 : makerId==='libido' ? 0.05 + (slot%4)*0.015 : makerId==='tokiwa' ? 0.01 : 0,
    availabilityWeight: round3(0.78 + ((slot*7+generation)%7)*0.05),
    concept:`${generationText}の${cfg.name}系列。${cfg.concept} ${nameKana}では${cfg.focusGroups.map(g=>({control:'制御',engine:'機関',sensor:'センサー',mobility:'駆動',compute:'演算',ai:'AI'}[g]??g)).join('・')}のうち個体に合う軸を選び、${weaponText}へ接続する。`,
    summary:`${cfg.name}の${generationText}系列「${nameKana}」。メーカー固有の運用思想を保ちながら、20系列ごとに得意能力と兵装の配分を変える。`,
    namingConcept:isG10
      ? `第10世代の命名方針に従い、造語ではなく実在する語・固有名詞「${nameKana}」を正式系列名として採用した。名称の由来を単なる外観モチーフにせず、${cfg.name}が重視する運用思想・得意能力・兵装選択へ結び付け、三年間の育成方針を読み取れる系列名として扱う。`
      : `「${nameKana}」は${cfg.name}の設計系譜を示す名称。世代更新ごとの改修記号を付け、同じ基礎思想がどのように変化したかを追える。`,
    developmentBackground:`${cfg.name}は${generationText}で現場データを再整理し、系列ごとに整備・展開・再構成の優先度を変えた。20系列を同じ万能機にせず、実戦で担当させる役割を明確に分けている。`,
    engineeringNotes:`主な設計候補は${cfg.focusGroups.map(g=>({control:'制御',engine:'機関',sensor:'センサー',mobility:'駆動',compute:'演算',ai:'AI'}[g]??g)).join('・')}。推奨兵装候補は${weaponText}で、系列番号によってどこへ比重を置くかが変わる。初期値だけでなく成長倍率と改修余地まで含めて役割を分けている。`,
    trainingNotes:'初期値だけで決めず、総合成長倍率と個体差を見て主軸を選ぶ。得意能力を兵装へ接続した後、信頼性や苦手比較項目を最低限補うとメーカーらしさを残しやすい。',
    weaponDoctrine:`${weaponText}を中心に、基礎能力と兵装6軸の相乗を作る。装備固定ではなく、成長した個体に合わせて主兵装を選び直せる余地を残す。`,
    marketPosition:`${generationText} / ${cfg.name}`,
    predecessorNumber:generation>1 ? number-20 : null,
    refitGeneration:generation,
    refitVersion:'4.8',
    tenthGeneration:isG10,
    cleanSheetNaming:isG10,
    realWordNaming:isG10,
    namingRule: makerId==='heritage' ? 'worldHeritage' : makerId==='libido' ? 'adultFetishAesthetic' : makerId==='tokiwa' ? 'furnitureAppliance' : null,
    sideBusinessBreakout: makerId==='tokiwa',
    travelCompanyOrigin: makerId==='heritage',
    adultModelOnly: makerId==='libido',
    combatSexaroid: makerId==='libido',
    designPriority: makerId==='libido' ? 'aestheticBeforeCombat' : null,
  };
  if (makerId==='libido') { const enriched=applyLibidoBodyMechanics(series,1); return {...enriched,...buildLibidoDescriptions(enriched,generation)}; }
  return series;
}

export const NEW_MANUFACTURER_PRE_G11_SERIES = Object.entries(MAKERS).flatMap(([makerId,cfg]) =>
  Array.from({length:10},(_,g)=>Array.from({length:20},(_,slot)=>buildSeries(makerId,cfg,g+1,slot))).flat()
);
